export function frontPage({bi,tx,state,topics,filtered}){
  const pool=filtered(topics,state.exam),next=pool.find(t=>!state.lessons.includes(t.id))||pool[0];
  const exams=[['all',bi('All exams','सभी परीक्षाएं')],['ssc','SSC'],['banking',bi('Banking','बैंकिंग')],['railways',bi('Railways','रेलवे')],['insurance',bi('Insurance','बीमा')]];
  return `<div class="mobile-front">
    <div class="front-intro"><div class="eyebrow">${bi('A LITTLE BETTER, EVERY DAY','हर दिन, थोड़ा बेहतर')}</div><h1>${bi('Your next <em>aha!</em> <br>starts here.','आपकी अगली <em>नई समझ</em> <br>यहीं से शुरू होती है।')}</h1><p>${bi('Understand it. Try it. Make it yours.','समझें। आजमाएं। अपना बनाएं।')}</p></div>
    <div class="exam-chips" role="group" aria-label="${bi('Choose your exam','अपनी परीक्षा चुनें')}">${exams.map(([id,name])=>`<button data-home-exam="${id}" aria-pressed="${state.exam===id}" class="${state.exam===id?'chosen':''}">${name}</button>`).join('')}</div>
    <section class="front-lab" aria-labelledby="front-lab-title"><div class="front-lab-copy"><span class="front-badge">✦ ${bi('THE 30-SECOND AHA','30 सेकंड की नई समझ')}</span><h2 id="front-lab-title">${bi('See what a <br>percentage means.','देखें कि प्रतिशत <br>का मतलब क्या है।')}</h2><p>${bi('Slide it. Watch the idea click.','स्लाइडर चलाएं। बात समझ में आएगी।')}</p><button class="front-start" data-lesson="percentages">${bi('Explore percentage lab','प्रतिशत लैब खोलें')}</button></div><div class="front-experiment"><div class="front-visual"><div class="front-grid" aria-hidden="true">${Array.from({length:100},(_,i)=>`<i class="${i<25?'on':''}"></i>`).join('')}</div><div class="front-reading"><output for="front-percent" id="front-value">25<span>%</span></output><span id="front-fraction">${bi('25 out of 100','100 में से 25')}</span><span class="front-visual-note">${bi('One square = 1%','एक वर्ग = 1%')}</span></div></div><label class="sr-only" for="front-percent">${bi('Try a percentage','प्रतिशत आजमाएं')}</label><input id="front-percent" type="range" min="0" max="100" value="25"><div class="front-range-labels"><span>0%</span><span>${bi('Drag to explore','खींचकर आजमाएं')}</span><span>100%</span></div></div></section>
    <button class="continue-card" data-lesson="${next.id}"><span class="topic-icon ${next.color}">${next.icon}</span><span class="continue-copy"><small>${state.lessons.length?bi('YOUR NEXT SMALL WIN','आपकी अगली छोटी जीत'):bi('A GREAT PLACE TO START','शुरुआत के लिए अच्छा विषय')}</small><strong>${tx(next.title)}</strong><span>${next.minutes} ${bi('min','मिनट')} <i>·</i> ${bi('Interactive lesson','इंटरैक्टिव पाठ')}</span></span><span class="continue-play" aria-hidden="true">▷</span></button>
    <section class="front-topics"><div class="section-top"><h2>${bi('What will you unlock?','आज क्या समझेंगे?')}</h2><button class="text-button" data-nav="learn">${bi('View all','सभी देखें')}</button></div><div class="front-topic-grid">${pool.map(t=>`<button class="front-topic" data-lesson="${t.id}"><span class="topic-icon ${t.color}">${t.icon}</span><span class="front-topic-subject">${t.subject==='quant'?bi('MATHS','गणित'):bi('REASONING','तर्कशक्ति')}</span><strong>${tx(t.title)}</strong><span>${t.minutes} ${bi('min','मिनट')} <i>·</i> 5 ${bi('questions','प्रश्न')}</span></button>`).join('')}</div></section>
    <section class="front-quick"><div><span class="eyebrow">${bi('PUT YOURSELF TO THE TEST','अपनी समझ परखें')}</span><h2>${bi('A little challenge.<br>A stronger you.','एक छोटी चुनौती।<br>एक बेहतर आप।')}</h2><p>${bi('Mix topics. Beat the clock. Learn from every answer.','विषय मिलाएं। समय में हल करें। हर उत्तर से सीखें।')}</p><button class="dark-button" data-nav="exam">${bi('Try a timed drill','समयबद्ध अभ्यास करें')}</button></div><span aria-hidden="true" class="front-clock">◷</span></section>
    <button class="front-progress" data-nav="progress"><span class="progress-ring" style="--completed:${state.lessons.length/6*100}%"><b>${state.lessons.length}<small>/6</small></b></span><span><strong>${bi('Little steps add up.','छोटे कदम जुड़ते जाते हैं।')}</strong><span>${bi('See your learning progress','अपनी अध्ययन प्रगति देखें')}</span></span><span class="progress-label">${bi('View','देखें')}</span></button>
    <div class="front-trust">${bi('Original questions · English + हिंदी · Learn at your pace','मौलिक प्रश्न · हिंदी + English · अपनी गति से सीखें')}</div>
  </div>`;
}
export function bindFrontPage({bi,onExam}){
  document.querySelectorAll('[data-home-exam]').forEach(button=>button.onclick=()=>onExam(button.dataset.homeExam));
  const slider=document.querySelector('#front-percent');if(!slider)return;
  slider.oninput=()=>{const n=Number(slider.value);document.querySelector('#front-value').innerHTML=`${n}<span>%</span>`;document.querySelector('#front-fraction').textContent=bi(`${n} out of 100`,`100 में से ${n}`);document.querySelectorAll('.front-grid i').forEach((cell,i)=>cell.classList.toggle('on',i<n));};
}
